<template>
  <div class="operation-page">
    <PageHero title="质检日报" icon="DocumentChecked" description="按北京时间定时整理检测任务的统计快照，可下载 Word、PDF、Excel 或 Markdown。计划不调用模型，也不代替人工复核与审批。"><template #actions><el-button :loading="loading" @click="load">刷新</el-button><el-button type="primary" @click="edit(null)"><AppIcon name="Plus" :size="16" />新建日报计划</el-button></template></PageHero>
    <el-alert v-if="error && rows.length" :title="error" type="warning" :closable="false" />
    <section class="operation-cards" aria-label="本人日报计划"><article v-for="row in rows" :key="row.schedule_id" class="operation-card"><h3>{{ row.name }}</h3><el-tag :type="enabled(row)?'primary':'info'">{{ enabled(row)?'已启用':'已暂停' }}</el-tag><p>执行时间 {{ ({'0 0 8 * * *':'每天 08:00','0 0 18 * * MON-FRI':'工作日 18:00'})[row.cron_expression]||row.cron_expression }} · UTC+8</p><p>下一次 {{ utcDisplay(row.next_fire_at) }}</p><p class="operation-muted">自动执行时统计前一天创建任务的当前状态；停机后保留待执行时点，不批量补发所有错过的时点。</p><div class="operation-actions"><el-button @click="edit(row)">调整计划</el-button><el-button type="primary" plain @click="prepareRun(row)">生成指定日期</el-button><el-button @click="openRuns(row)">查看日报</el-button></div></article></section>
    <CollectionEmptyState v-if="!rows.length" :loading="loading" :error="error" empty-title="创建第一份质检日报计划" empty-description="选择固定时间，系统将保存可追溯的统计快照。" @retry="load" />
    <el-dialog v-model="editVisible" :title="selected?'调整日报计划':'新建日报计划'" width="min(520px,94vw)" :close-on-click-modal="!busy" :close-on-press-escape="!busy" :before-close="closeEdit"><form class="operation-form" @submit.prevent="save"><label>计划名称<el-input v-model="form.name" maxlength="120" required :disabled="busy" /></label><label>执行时间 · UTC+8<el-select v-model="preset" :disabled="busy" @change="applyPreset"><el-option label="每天 08:00" value="0 0 8 * * *" /><el-option label="工作日 18:00" value="0 0 18 * * MON-FRI" /><el-option label="自定义 Cron" value="custom" /></el-select></label><label v-if="preset==='custom'">六段 Cron 表达式<el-input v-model="form.cronExpression" :disabled="busy" maxlength="100" required /></label><p class="operation-muted">秒位固定为 0。一次任务仅生成统计快照。暂停计划仅停止后续定时触发，已入队的日报继续生成。</p><el-switch v-model="form.enabled" :disabled="busy" active-text="启用定时执行" inactive-text="保留为暂停计划" /><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><el-button type="primary" native-type="submit" :loading="busy" :disabled="!form.name.trim()">保存计划</el-button></form></el-dialog>
    <el-dialog v-model="runVisible" title="生成指定日期日报" width="min(460px,94vw)" :close-on-click-modal="!busy" :close-on-press-escape="!busy" :before-close="closeRun"><form class="operation-form" @submit.prevent="generate"><p>{{ selected?.name }}</p><label>统计日期 · UTC+8<input v-model="reportDate" type="date" required :max="today" :disabled="busy" /></label><p class="operation-muted">保存为独立统计快照，既有日报保持不变。可在日报列表中刷新查看生成状态。</p><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><el-button type="primary" native-type="submit" :loading="busy" :disabled="!reportDate">提交生成</el-button></form></el-dialog>
    <el-drawer v-model="runsVisible" title="日报与交付记录" size="min(760px,100vw)"><div class="operation-toolbar"><el-button :loading="runsLoading" @click="openRuns(currentSchedule)">刷新状态</el-button><el-select v-model="format" aria-label="日报文件格式" style="width:150px"><el-option label="Word" value="docx" /><el-option label="PDF" value="pdf" /><el-option label="Excel" value="xlsx" /><el-option label="Markdown" value="md" /></el-select></div><el-alert v-if="runsError" :title="runsError" type="warning" :closable="false" /><article v-for="run in runs" :key="run.run_id" class="operation-chunk"><h3>{{ run.report_date }} · {{ states[run.status]||run.status }}</h3><p class="operation-muted">生成于 {{ utcDisplay(run.finished_at) }}<span v-if="run.error_code"> · {{ ({AUTHORITY_REVOKED:'账号权限已变化',SNAPSHOT_UNAVAILABLE:'统计资料暂不可读取'})[run.error_code]||'生成状态待核对' }}</span></p><p v-if="run.snapshot_sha256" class="operation-muted">快照 SHA-256 {{ run.snapshot_sha256 }}</p><el-button v-if="run.status==='COMPLETED'" :loading="busy" @click="download(run)"><AppIcon name="Download" :size="15" />下载日报</el-button></article><p v-if="!runs.length&&!runsLoading&&!runsError" class="operation-muted">暂无日报，请先等待计划执行或生成指定日期。</p></el-drawer>
  </div>
</template>
<script setup>
import { onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import request from '../api/request'
import { useAccountOperationScope } from '../composables/useAccountOperationScope'
import { operationData, operationError, utcDisplay, deliverFile } from '../utils/qualityOperations'
import { beijingDateTime } from '../utils/beijingTime'
import AppIcon from '../components/AppIcon.vue'
import CollectionEmptyState from '../components/CollectionEmptyState.vue'
import '../assets/quality-operations.css'
const rows=ref([]),loading=ref(false),error=ref(''),busy=ref(false),formError=ref(''),editVisible=ref(false),runVisible=ref(false),selected=ref(null),preset=ref('0 0 8 * * *'),reportDate=ref(''),today=beijingDateTime().slice(0,10),requestId=ref(''),runsVisible=ref(false),runs=ref([]),runsLoading=ref(false),runsError=ref(''),currentSchedule=ref(null),format=ref('md')
const form=reactive({name:'',cronExpression:'0 0 8 * * *',enabled:false,expectedVersion:0,requestId:''})
const scope=useAccountOperationScope(()=>{rows.value=[];runs.value=[];currentSchedule.value=null;selected.value=null;editVisible.value=false;runVisible.value=false;runsVisible.value=false;loading.value=false;runsLoading.value=false;busy.value=false;error.value='';formError.value='';runsError.value='';reportDate.value='';form.name='';form.requestId='';requestId.value=''}),listing=scope.channel(),runRead=scope.channel()
const base='/api/quality/digests',headers={'X-Digest-Action':'update'},states={PENDING:'等待生成',RUNNING:'正在生成',COMPLETED:'已生成',FAILED:'生成失败',BLOCKED:'权限已变化，停止生成'}
const enabled=row=>row.enabled===true||row.enabled===1||row.enabled==='1'
async function load(){const token=listing.begin();loading.value=true;error.value='';try{const data=operationData(await request.get(base,{signal:token.signal}));if(!listing.current(token))return;if(!Array.isArray(data))throw new Error('日报计划未完整读取');rows.value=data}catch(e){if(listing.current(token)){rows.value=[];error.value=operationError(e,true)}}finally{if(listing.current(token))loading.value=false}}
function edit(row){if(busy.value)return;selected.value=row;Object.assign(form,{name:row?.name||'',cronExpression:row?.cron_expression||'0 0 8 * * *',enabled:row?enabled(row):false,expectedVersion:row?.version||0,requestId:crypto.randomUUID()});preset.value=['0 0 8 * * *','0 0 18 * * MON-FRI'].includes(form.cronExpression)?form.cronExpression:'custom';formError.value='';editVisible.value=true}
function applyPreset(value){if(value!=='custom')form.cronExpression=value}
function closeEdit(done){if(!busy.value)done()}function closeRun(done){if(!busy.value)done()}
async function save(){if(busy.value)return;const token=scope.stamp();busy.value=true;formError.value='';try{operationData(await request.request({url:selected.value?base+'/'+selected.value.schedule_id:base,method:selected.value?'PUT':'POST',data:{...form},headers}));if(!scope.current(token))return;editVisible.value=false;await load()}catch(e){if(scope.current(token))formError.value=operationError(e)+'；重试保留当前请求编号'}finally{if(scope.current(token))busy.value=false}}
function prepareRun(row){if(busy.value)return;selected.value=row;const stamp=new Date();stamp.setUTCDate(stamp.getUTCDate()-1);reportDate.value=beijingDateTime(stamp).slice(0,10);requestId.value=crypto.randomUUID();formError.value='';runVisible.value=true}
async function generate(){if(busy.value||!selected.value)return;const token=scope.stamp(),row=selected.value;busy.value=true;formError.value='';try{operationData(await request.post(base+'/'+row.schedule_id+'/runs',{reportDate:reportDate.value,expectedVersion:row.version,requestId:requestId.value},{headers}));if(!scope.current(token))return;runVisible.value=false;await openRuns(row)}catch(e){if(scope.current(token))formError.value=operationError(e)+'；重试保留当前生成编号'}finally{if(scope.current(token))busy.value=false}}
async function openRuns(row){if(!row)return;const changed=currentSchedule.value?.schedule_id!==row.schedule_id;currentSchedule.value=row;runsVisible.value=true;if(changed)runs.value=[];const token=runRead.begin();runsLoading.value=true;runsError.value='';try{const data=operationData(await request.get(base+'/'+row.schedule_id+'/runs',{signal:token.signal}));if(!runRead.current(token))return;if(!Array.isArray(data))throw new Error('日报列表未完整读取');runs.value=data}catch(e){if(runRead.current(token)){runs.value=[];runsError.value=operationError(e)}}finally{if(runRead.current(token))runsLoading.value=false}}
async function download(run){if(busy.value)return;const token=scope.stamp(),extension=format.value;busy.value=true;runsError.value='';try{const response=await request.post(base+'/runs/'+run.run_id+'/export',null,{headers,params:{format:extension},responseType:'blob',timeout:60000});const type={md:'text/markdown',pdf:'application/pdf',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}[extension];await deliverFile(response,'质检日报-'+run.report_date+'.'+extension,[type],()=>scope.current(token))}catch(e){if(scope.current(token))runsError.value=operationError(e)}finally{if(scope.current(token))busy.value=false}}
let timer,alive=true
onMounted(async()=>{await load();if(!alive)return;timer=window.setInterval(()=>{if(!document.hidden&&runsVisible.value&&!runsLoading.value&&currentSchedule.value)openRuns(currentSchedule.value)},15000)})
onBeforeUnmount(()=>{alive=false;window.clearInterval(timer)})
</script>
